const webhookRan = $('Receive result').isExecuted;
const pollRan = $('Fetch LIS results').isExecuted;
const incomingItems = webhookRan ? $('Receive result').all() : (pollRan ? $('Fetch LIS results').all() : []);

function sheetRows(nodeName) {
  return $(nodeName).all().map((item) => item.json).filter((row) => {
    if (!row || typeof row !== 'object') return false;
    return Object.keys(row).some((key) => {
      const value = row[key];
      return value !== undefined && value !== null && String(value).trim() !== '';
    });
  });
}

function blank(value) {
  return value === undefined || value === null || String(value).trim() === '';
}

function asNumber(value) {
  if (blank(value)) return null;
  const parsed = Number(String(value).trim().split(',').join(''));
  return Number.isFinite(parsed) ? parsed : null;
}

function stripSpaces(value) {
  return String(value).split('').filter((ch) => ch !== ' ' && ch.charCodeAt(0) !== 9).join('');
}

function normalizeUnit(unit) {
  const raw = String(unit ?? '').trim();
  const compact = stripSpaces(raw).toLowerCase().split('µ').join('μ');
  if (compact === 'mg/dl') return 'mg/dL';
  if (compact === 'mmol/l') return 'mmol/L';
  if (compact === 'umol/l' || compact === 'μmol/l') return 'μmol/L';
  if (compact === 'g/dl') return 'g/dL';
  return raw;
}

function roundValue(value) {
  return Math.round(value * 10000) / 10000;
}

function component(field, index) {
  return String(field || '').split('^')[index] || '';
}

function formatRange(low, high, raw) {
  if (!blank(raw)) return String(raw).trim();
  const hasLow = !blank(low);
  const hasHigh = !blank(high);
  if (hasLow && hasHigh) return String(low).trim() + '-' + String(high).trim();
  if (hasHigh) return '<' + String(high).trim();
  if (hasLow) return '>' + String(low).trim();
  return '';
}

function linesOf(raw) {
  const text = String(raw);
  const out = [];
  let current = '';
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code === 13 || code === 10) {
      if (current.trim()) out.push(current.trim());
      current = '';
    } else {
      current += text[i];
    }
  }
  if (current.trim()) out.push(current.trim());
  return out;
}

function shortDoctor(fields) {
  if (!fields || fields.length >= 17) return '';
  for (let i = fields.length - 1; i >= 8; i--) {
    const candidate = component(fields[i], 0).trim();
    if (!candidate || /^\d{8,14}$/.test(candidate)) continue;
    return candidate;
  }
  return '';
}

function parseOru(raw) {
  const segments = linesOf(raw);
  if (!segments.length || !segments[0].startsWith('MSH')) return null;
  let patientId = '';
  let doctorId = '';
  let fillerId = '';
  let abbreviatedDoctor = '';
  const observations = [];
  for (const segment of segments) {
    const fields = segment.split('|');
    const kind = fields[0];
    if (kind === 'PID') patientId = component(fields[3], 0);
    if (kind === 'ORC') {
      if (!fillerId) fillerId = component(fields[3], 0) || component(fields[2], 0);
      if (!doctorId) doctorId = component(fields[12], 0);
    }
    if (kind === 'OBR') {
      fillerId = component(fields[3], 0) || component(fields[2], 0) || fillerId;
      if (!doctorId) doctorId = component(fields[16], 0);
      if (!abbreviatedDoctor) abbreviatedDoctor = shortDoctor(fields);
    }
    if (kind === 'OBX') {
      observations.push({
        setId: fields[1] || String(observations.length + 1),
        testCode: component(fields[3], 0),
        value: fields[5] || '',
        unit: component(fields[6], 0),
        referenceRange: fields[7] || '',
      });
    }
  }
  if (!doctorId) doctorId = abbreviatedDoctor;
  if (!observations.length) {
    return [{
      result_id: fillerId,
      patient_id: patientId,
      doctor_id: doctorId,
      test_code: '',
      value: '',
      unit: '',
      reference_range: '',
      source: 'hl7',
      parse_error: 'HL7 ORU has no OBX segment.',
    }];
  }
  return observations.map((row) => ({
    result_id: (fillerId || 'ORU') + '-' + (row.testCode || 'TEST') + '-' + row.setId,
    patient_id: patientId,
    doctor_id: doctorId,
    test_code: row.testCode,
    value: component(row.value, 0) || row.value,
    unit: row.unit,
    reference_range: row.referenceRange,
    source: 'hl7',
  }));
}

function parseJsonMaybe(text) {
  const trimmed = String(text).trim();
  if (!trimmed || (trimmed[0] !== '{' && trimmed[0] !== '[')) return null;
  try {
    return JSON.parse(trimmed);
  } catch (error) {
    return null;
  }
}

function expand(value) {
  if (value === undefined || value === null || value === '') return [];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    if (trimmed.startsWith('MSH')) return parseOru(trimmed) || [];
    const parsed = parseJsonMaybe(trimmed);
    return parsed === null ? [] : expand(parsed);
  }
  if (Array.isArray(value)) return value.flatMap(expand);
  if (typeof value !== 'object') return [];
  if (!blank(value.hl7)) return parseOru(value.hl7) || [];
  if (!blank(value.HL7)) return parseOru(value.HL7) || [];
  if (Array.isArray(value.results)) return value.results.flatMap(expand);
  if (Array.isArray(value.data)) return value.data.flatMap(expand);
  if (typeof value.data === 'string') return expand(value.data);
  if (value.body !== undefined && (value.headers || value.webhookUrl || value.executionMode)) return expand(value.body);
  return [{
    result_id: value.result_id,
    patient_id: value.patient_id,
    doctor_id: value.doctor_id,
    test_code: value.test_code,
    value: value.value,
    unit: value.unit,
    reference_range: formatRange(value.reference_low, value.reference_high, value.reference_range || value.referenceRange),
    source: value.source || 'rest',
  }];
}

function payloadsFrom(items) {
  return items.flatMap((item) => {
    const json = item.json || {};
    if (typeof json.data === 'string') return expand(json.data);
    if (json.body !== undefined) return expand(json.body);
    if (!blank(json.hl7) || !blank(json.HL7)) return expand(json);
    return expand(json);
  });
}

const limits = sheetRows('Read limits');
const doctors = sheetRows('Read doctors');
const logRows = sheetRows('Read log');
const payloads = payloadsFrom(incomingItems);

if (!payloads.length) {
  if (!webhookRan && pollRan) return [];
  return [{
    json: {
      when: new Date().toISOString(),
      result_id: '',
      patient_id: '',
      doctor_id: '',
      test_code: '',
      value: '',
      unit: '',
      reference_range: '',
      severity: '',
      route: 'lab',
      what_happened: 'Needs review',
      message: 'No lab result in the request. Send generic JSON or an HL7 ORU message.',
      execution_id: $execution.id,
      doctor_slack: '',
      doctor_email: '',
      backup_slack: '',
      doctor_phone: '',
      doctor_name: '',
      test_name: '',
      limit_hit: '',
      limit_side: '',
      fallback_note: '',
      conversion_note: '',
      source: webhookRan ? 'rest' : 'poll',
    },
  }];
}

const notified = new Set([
  'Processing',
  'Waiting for acknowledgment',
  'Acknowledged',
  'Backup notified',
  'Emailed doctor',
]);

function classify(payload) {
  const resultId = blank(payload.result_id) ? '' : String(payload.result_id).trim();
  const patientId = blank(payload.patient_id) ? '' : String(payload.patient_id).trim();
  const doctorId = blank(payload.doctor_id) ? '' : String(payload.doctor_id).trim();
  const testCode = blank(payload.test_code) ? '' : String(payload.test_code).trim().toUpperCase();
  const rawUnit = blank(payload.unit) ? '' : normalizeUnit(payload.unit);
  const rawValue = asNumber(payload.value);
  const referenceRange = blank(payload.reference_range) ? '' : String(payload.reference_range).trim();
  const base = {
    when: new Date().toISOString(),
    result_id: resultId,
    patient_id: patientId,
    doctor_id: doctorId,
    test_code: testCode,
    value: rawValue === null ? (payload.value ?? '') : rawValue,
    unit: rawUnit,
    reference_range: referenceRange,
    severity: '',
    what_happened: '',
    message: '',
    execution_id: $execution.id,
    route: 'lab',
    doctor_slack: '',
    doctor_email: '',
    backup_slack: '',
    doctor_phone: '',
    doctor_name: '',
    test_name: '',
    limit_hit: '',
    limit_side: '',
    fallback_note: '',
    conversion_note: '',
    source: payload.source || 'rest',
  };
  const done = (overrides) => ({ ...base, ...overrides });

  if (payload.parse_error) {
    return done({ route: 'lab', what_happened: 'Needs review', message: payload.parse_error });
  }
  if (!resultId || !patientId || !doctorId || !testCode || !rawUnit || rawValue === null || !referenceRange) {
    return done({
      route: 'lab',
      what_happened: 'Needs review',
      message: 'Missing result_id, patient_id, doctor_id, test_code, unit, a numeric value, or reference range.',
    });
  }
  const duplicate = logRows.some((row) => String(row.result_id ?? '').trim() === resultId && notified.has(String(row.what_happened ?? '').trim()));
  if (duplicate) {
    return done({
      route: 'duplicate',
      what_happened: 'Already notified — skipped',
      message: 'This result_id already has a notified log row. Skipped.',
    });
  }
  const limit = limits.find((row) => String(row.test_code ?? '').trim().toUpperCase() === testCode);
  const limitKeys = ['critical_low', 'abnormal_low', 'abnormal_high', 'critical_high'];
  const hasAnyLimit = Boolean(limit) && limitKeys.some((key) => asNumber(limit[key]) !== null);
  if (!limit || !hasAnyLimit) {
    return done({
      route: 'lab',
      what_happened: 'Needs review',
      message: !limit ? 'Test code ' + testCode + ' is not in Limits.' : 'Test code ' + testCode + ' has no limits set.',
      test_name: limit ? String(limit.test_name ?? '') : '',
    });
  }
  const limitUnit = normalizeUnit(limit.unit);
  const testName = blank(limit.test_name) ? testCode : String(limit.test_name).trim();
  const nameLower = testName.toLowerCase();
  const isGlucose = testCode === 'GLU' || nameLower.includes('glucose');
  const isCreatinine = ['CREAT', 'CREATININE', 'CRE', 'CR'].includes(testCode) || nameLower.includes('creatinine');
  let value = rawValue;
  let unit = rawUnit;
  let conversionNote = '';
  if (rawUnit !== limitUnit) {
    if (isGlucose && rawUnit === 'mmol/L' && limitUnit === 'mg/dL') {
      value = roundValue(rawValue * 18.0182);
      unit = limitUnit;
      conversionNote = 'Converted from ' + rawValue + ' mmol/L.';
    } else if (isCreatinine && rawUnit === 'μmol/L' && limitUnit === 'mg/dL') {
      value = roundValue(rawValue / 88.4);
      unit = limitUnit;
      conversionNote = 'Converted from ' + rawValue + ' μmol/L.';
    } else {
      return done({
        route: 'lab',
        what_happened: 'Needs review',
        message: 'Unit ' + rawUnit + ' does not match Limits unit ' + limitUnit + ' and is not a supported conversion.',
        test_name: testName,
      });
    }
  }
  const doctor = doctors.find((row) => String(row.doctor_id ?? '').trim() === doctorId);
  if (!doctor) {
    return done({
      route: 'lab',
      what_happened: 'Needs review',
      message: 'Doctor ' + doctorId + ' is not in Doctors.',
      value,
      unit,
      test_name: testName,
      conversion_note: conversionNote,
    });
  }
  const doctorSlack = blank(doctor.slack_id) ? '' : String(doctor.slack_id).trim();
  const doctorEmail = blank(doctor.email) ? '' : String(doctor.email).trim();
  const backupSlack = blank(doctor.backup_slack_id) ? '' : String(doctor.backup_slack_id).trim();
  const doctorPhone = [doctor.phone, doctor.sms, doctor.mobile].map((entry) => (blank(entry) ? '' : String(entry).trim())).find(Boolean) || '';
  const doctorName = blank(doctor.name) ? '' : String(doctor.name).trim();
  const criticalLow = asNumber(limit.critical_low);
  const criticalHigh = asNumber(limit.critical_high);
  const abnormalLow = asNumber(limit.abnormal_low);
  const abnormalHigh = asNumber(limit.abnormal_high);
  let severity = 'normal';
  let limitHit = '';
  let limitSide = '';
  if (criticalLow !== null && value <= criticalLow) {
    severity = 'critical';
    limitHit = String(criticalLow);
    limitSide = 'at or below';
  } else if (criticalHigh !== null && value >= criticalHigh) {
    severity = 'critical';
    limitHit = String(criticalHigh);
    limitSide = 'at or above';
  } else if (abnormalLow !== null && value <= abnormalLow) {
    severity = 'abnormal';
    limitHit = String(abnormalLow);
    limitSide = 'at or below';
  } else if (abnormalHigh !== null && value >= abnormalHigh) {
    severity = 'abnormal';
    limitHit = String(abnormalHigh);
    limitSide = 'at or above';
  }
  const shared = {
    value,
    unit,
    severity,
    test_name: testName,
    doctor_slack: doctorSlack,
    doctor_email: doctorEmail,
    backup_slack: backupSlack,
    doctor_phone: doctorPhone,
    doctor_name: doctorName,
    limit_hit: limitHit,
    limit_side: limitSide,
    conversion_note: conversionNote,
  };
  function fallbackNote(action) {
    const title = severity.charAt(0).toUpperCase() + severity.slice(1);
    return title + ' result: ' + testName + ' is ' + value + ' ' + unit + ' (' + limitSide + ' ' + limitHit + '). ' + action;
  }
  if (severity === 'critical') {
    if (!doctorSlack) {
      return done({
        ...shared,
        route: 'lab',
        what_happened: 'Needs review',
        message: 'Critical result but the doctor has no Slack id.',
      });
    }
    const fallback = fallbackNote('Please review and acknowledge.');
    return done({ ...shared, route: 'critical', message: fallback, fallback_note: fallback });
  }
  if (severity === 'abnormal') {
    if (!doctorEmail) {
      return done({
        ...shared,
        route: 'lab',
        what_happened: 'Needs review',
        message: 'Abnormal result but the doctor has no email.',
      });
    }
    const fallback = fallbackNote('Please review.');
    return done({ ...shared, route: 'abnormal', message: fallback, fallback_note: fallback });
  }
  return done({
    ...shared,
    route: 'normal',
    what_happened: 'Normal — logged only',
    message: 'Within limits. Logged only.',
  });
}

return payloads.map((payload) => ({ json: classify(payload) }));

const prepared = $('Prepare result').item.json;
const ai = $input.item.json || {};
function pick(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;
  const headline = typeof obj.headline === 'string' ? obj.headline.trim() : '';
  const action = typeof obj.action === 'string' ? obj.action.trim() : '';
  const note = typeof obj.note === 'string' ? obj.note.trim() : '';
  if (!headline && !action && !note) return null;
  return { note: note, headline: headline, action: action };
}
function parseText(text) {
  if (typeof text !== 'string') return null;
  const trimmed = text.trim();
  if (!trimmed.startsWith('{')) return null;
  try { return pick(JSON.parse(trimmed)); } catch (error) { return null; }
}
let chosen = pick(ai) || parseText(ai.mergedResponse) || parseText(ai.text) || parseText(ai.output);
if (!chosen && ai.content && Array.isArray(ai.content.parts)) {
  chosen = parseText(ai.content.parts.map(function (part) { return part && part.text ? part.text : ''; }).join(''));
}
if (!chosen && typeof ai.mergedResponse === 'string' && ai.mergedResponse.trim() && ai.mergedResponse.trim().charAt(0) !== '{') {
  chosen = { note: ai.mergedResponse.trim(), headline: '', action: '' };
}
const fallback = prepared.fallback_note || prepared.message || '';
const requiredAction = prepared.severity === 'critical' ? 'Please review and acknowledge.' : 'Please review.';
const valueText = prepared.value === undefined || prepared.value === null ? '' : String(prepared.value);
const unitText = prepared.unit ? String(prepared.unit) : '';
function restates(text) {
  if (!text) return false;
  if (valueText && text.indexOf(valueText) === -1) return false;
  if (unitText && text.indexOf(unitText) === -1) return false;
  if (text.indexOf(requiredAction) === -1) return false;
  return true;
}
let note = '';
if (chosen) {
  const built = [chosen.headline, chosen.action].filter(Boolean).join(' ');
  if (restates(built)) note = built;
  else if (restates(chosen.note)) note = chosen.note;
}
if (!note) note = fallback;
return { json: Object.assign({}, prepared, { doctor_note: note, note_headline: chosen ? chosen.headline : '', note_action: chosen ? chosen.action : '' }) };
